head.script:
scwin.screenId = "jldods60001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_acntclsMmdd1_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4_txt", fn: function(){ return ((dma_hm.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "hm.acntclsMmdd4"); })()) !== ''); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb6", fn: function () { return String(dma_hm.get("acntclsMmdd1")) + "월"; } },
        { childId: "__rb7", fn: function () { return String(dma_hm.get("acntclsMmdd2")) + "월"; } },
        { childId: "__rb8", fn: function () { return String(dma_hm.get("acntclsMmdd3")) + "월"; } },
        { childId: "__rb9", fn: function () { return String(dma_hm.get("acntclsMmdd4")) + "월"; } },
        { childId: "__rb10", fn: function () { return String(dma_hm.get("indNm")) + "(" + String(dma_hm.get("stdIndCd")) + ")"; } },
        { childId: "__rb11", fn: function () { return String(dma_hm.get("addr")) + " " + String(dma_hm.get("dtlAddr")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldods60001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods60001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_headofcLoc_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_headofcLoc_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_headofcLoc');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_headofcLoc'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.goViewer === 'function') { scwin.goViewer(r["acptNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.goViewer (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.goViewer'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_headofcLoc.oncellclick' });
    }
};

